use verus::prelude::*;

verus! {

    /// Given a slice of i32, returns a fresh Vec<i32> containing
    /// the same elements in reverse order.
    pub fn reverse(a: &[i32]) -> (res: Vec<i32>)
        ensures res.len() == a.len()
        ensures forall(|i: usize| i < a.len() ==> res[i] == a[a.len() - 1 - i])
    {
        // We build up the result vector one element at a time.
        let mut res: Vec<i32> = Vec::new();
        let n: usize = a.len();
        let mut i: usize = 0;

        // Loop invariant:
        //  1) 0 ≤ i ≤ n
        //  2) res.len() == i
        //  3) For all j < i, res[j] == a[n-1-j]
        // Decreases clause ensures termination.
        while i < n
            invariant i <= n
            invariant res.len() == i
            invariant forall(|j: usize| j < i ==> res[j] == a[n - 1 - j])
            decreases n - i
        {
            // Push the next reversed element
            res.push(a[n - 1 - i]);
            i += 1;
        }

        // At this point i == n, so res.len() == n, and
        // by the invariant we have res[j] == a[n - 1 - j] for all j < n.
        res
    }
}